-- READ ONLY. Schema metadata for encrypted database backups. No row data here.
SELECT pg_catalog.jsonb_build_object(
 'server_version',pg_catalog.current_setting('server_version'),
 'extensions',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',e.extname,'schema',n.nspname,'version',e.extversion)) FROM pg_catalog.pg_extension e JOIN pg_catalog.pg_namespace n ON n.oid=e.extnamespace),
 'types',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',t.typname,'kind',t.typtype,'labels',(SELECT pg_catalog.jsonb_agg(en.enumlabel ORDER BY en.enumsortorder) FROM pg_catalog.pg_enum en WHERE en.enumtypid=t.oid))) FROM pg_catalog.pg_type t JOIN pg_catalog.pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype IN ('e','d','r','m') AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_depend dep WHERE dep.classid='pg_catalog.pg_type'::pg_catalog.regclass AND dep.objid=t.oid AND dep.deptype='e')),
 'relations',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('oid',c.oid,'name',c.relname,'kind',c.relkind,'options',c.reloptions,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,'persistence',c.relpersistence,'owner',pg_catalog.pg_get_userbyid(c.relowner))) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S','f') AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_depend dep WHERE dep.classid='pg_catalog.pg_class'::pg_catalog.regclass AND dep.objid=c.oid AND dep.deptype='e')),
 'columns',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('table',c.relname,'name',a.attname,'position',a.attnum,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid),'collation',CASE WHEN a.attcollation<>t.typcollation THEN a.attcollation::pg_catalog.regcollation::text END)) FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_type t ON t.oid=a.atttypid LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relkind IN ('r','p','f') AND a.attnum>0 AND NOT a.attisdropped),
 'sequences',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',c.relname,'type',pg_catalog.format_type(s.seqtypid,NULL),'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle,'owned_table',oc.relname,'owned_column',oa.attname,'dependency',dep.deptype)) FROM pg_catalog.pg_sequence s JOIN pg_catalog.pg_class c ON c.oid=s.seqrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_catalog.pg_depend dep ON dep.classid='pg_catalog.pg_class'::pg_catalog.regclass AND dep.objid=c.oid AND dep.deptype IN ('a','i') LEFT JOIN pg_catalog.pg_class oc ON oc.oid=dep.refobjid LEFT JOIN pg_catalog.pg_attribute oa ON oa.attrelid=oc.oid AND oa.attnum=dep.refobjsubid WHERE n.nspname='public'),
 'constraints',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('table',c.relname,'name',con.conname,'type',con.contype,'definition',pg_catalog.pg_get_constraintdef(con.oid))) FROM pg_catalog.pg_constraint con JOIN pg_catalog.pg_class c ON c.oid=con.conrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'),
 'indexes',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('table',c.relname,'name',ic.relname,'definition',pg_catalog.pg_get_indexdef(i.indexrelid))) FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indrelid JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_constraint con WHERE con.conindid=i.indexrelid)),
 'functions',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',p.proname,'signature',p.oid::pg_catalog.regprocedure::text,'definition',pg_catalog.pg_get_functiondef(p.oid),'security_definer',p.prosecdef,'config',p.proconfig,'owner',pg_catalog.pg_get_userbyid(p.proowner))) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind IN ('f','p') AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_depend dep WHERE dep.classid='pg_catalog.pg_proc'::pg_catalog.regclass AND dep.objid=p.oid AND dep.deptype='e')),
 'views',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('oid',c.oid,'name',c.relname,'kind',c.relkind,'definition',pg_catalog.pg_get_viewdef(c.oid,true),'dependencies',(SELECT pg_catalog.jsonb_agg(DISTINCT d.refobjid) FROM pg_catalog.pg_rewrite rw JOIN pg_catalog.pg_depend d ON d.objid=rw.oid WHERE rw.ev_class=c.oid AND d.refclassid='pg_catalog.pg_class'::pg_catalog.regclass AND d.refobjid<>c.oid))) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m') AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_depend dep WHERE dep.classid='pg_catalog.pg_class'::pg_catalog.regclass AND dep.objid=c.oid AND dep.deptype='e')),
 'triggers',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',n.nspname,'table',c.relname,'name',tg.tgname,'enabled',tg.tgenabled,'definition',pg_catalog.pg_get_triggerdef(tg.oid))) FROM pg_catalog.pg_trigger tg JOIN pg_catalog.pg_class c ON c.oid=tg.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_proc f ON f.oid=tg.tgfoid WHERE NOT tg.tgisinternal AND (n.nspname='public' OR (n.nspname IN ('auth','storage') AND f.pronamespace='public'::pg_catalog.regnamespace))),
 'policies',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'check',with_check)) FROM pg_catalog.pg_policies WHERE schemaname IN ('public','storage')),
 'grants',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',n.nspname,'table',c.relname,'kind',c.relkind,'grantee',CASE WHEN acl.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(acl.grantee) END,'privilege',acl.privilege_type,'grantable',acl.is_grantable)) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(c.relacl,pg_catalog.acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner))) acl WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S')),
 'column_grants',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('table',c.relname,'column',a.attname,'grantee',CASE WHEN acl.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(acl.grantee) END,'privilege',acl.privilege_type,'grantable',acl.is_grantable)) FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(a.attacl) acl WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped),
 'function_grants',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('signature',p.oid::pg_catalog.regprocedure::text,'grantee',CASE WHEN acl.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(acl.grantee) END,'privilege',acl.privilege_type,'grantable',acl.is_grantable)) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) acl WHERE n.nspname='public' AND p.prokind IN ('f','p') AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_depend dep WHERE dep.classid='pg_catalog.pg_proc'::pg_catalog.regclass AND dep.objid=p.oid AND dep.deptype='e')),
 'event_triggers',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',e.evtname,'event',e.evtevent,'enabled',e.evtenabled,'tags',e.evttags,'function',p.proname)) FROM pg_catalog.pg_event_trigger e JOIN pg_catalog.pg_proc p ON p.oid=e.evtfoid WHERE p.pronamespace='public'::pg_catalog.regnamespace),
 'backup_auth_tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='auth' AND c.relname IN ('users','identities','mfa_factors') AND c.relkind='r'),
 'backup_auth_types',(SELECT jsonb_agg(jsonb_build_object('name',t.typname,'labels',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid))) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='auth' AND t.typtype='e'),
 'backup_auth_columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='auth' AND c.relname IN ('users','identities','mfa_factors') AND a.attnum>0 AND NOT a.attisdropped),
 'backup_auth_constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',con.conname,'type',con.contype,'definition',pg_get_constraintdef(con.oid))) FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='auth' AND c.relname IN ('users','identities','mfa_factors')),
 'buckets',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) FROM storage.buckets)
) AS schema_export;
